// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {MY_BANK, Log} from "../src/MY_BANK.sol";

uint256 constant VALUE_CAP = 1000000000000000000000000000000;

contract InvMutTest is Test {
    MY_BANK c;
    function setUp() public { c = new MY_BANK(address(new Log())); }

    function testFuzz_property(uint256 amount1, uint256 amount2, address actor) public {
        vm.assume(amount1 <= VALUE_CAP);
        vm.assume(amount2 <= VALUE_CAP);
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));
        amount1 = bound(amount1, 0, 1000 ether);
        amount2 = bound(amount2, 0, 1000 ether);
        vm.assume(amount1 + amount2 >= amount1); // no overflow

        vm.deal(actor, amount1 + amount2);

        vm.prank(actor);
        c.Put{value: amount1}(0);
        vm.prank(actor);
        c.Put{value: amount2}(0);

        (, uint256 balance) = c.Acc(actor);
        assertTrue(balance == amount1 + amount2);
    }
}
